-- HomeSpace: 300 listing DEMO, một listing cho mỗi điểm trong JSON đi kèm.
-- Nguồn: homespace_seed_300_duong_govap.json. Không sửa/nội suy lại tọa độ.
-- Tọa độ là approximate_from_user_map, KHÔNG phải vị trí căn nhà đã xác minh.
-- Trường chưa xác minh giữ NULL; mã phường được đối chiếu chính xác tỉnh + tên với JSON Vietmap admin_new của frontend.
-- Dùng CSDL tạo lại từ đầu; khởi động Core đã cập nhật để tạo schema/catalog trước.
-- Chỉ dùng local/dev. SQL tự chứa snapshot JSON nên chạy được bằng pgAdmin.
-- Sinh lại snapshot: node scripts/build-listings-seed.mjs (tại hs-infra).
-- Chạy lại upsert cùng ID, không xóa tin thật/seed cũ và không thay đổi schema.
-- 100 HOUSE, 100 APARTMENT, 100 ROOM; giá/nội thất/chính sách/ảnh là dữ liệu mẫu.

BEGIN;

CREATE TEMP TABLE hs_seed_config ON COMMIT DROP AS
SELECT u.id AS owner_id
FROM users u
JOIN roles r ON r.id = u.role_id
WHERE u.active IS TRUE AND upper(r.name) = 'ADMIN'
  AND lower(u.username) = 'homespace'
LIMIT 1;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM hs_seed_config) THEN
        RAISE EXCEPTION 'Không tìm thấy users.active=true có role ADMIN. Hãy seed tài khoản trước khi chạy.';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM amenities WHERE active IS TRUE)
       OR NOT EXISTS (SELECT 1 FROM furnishing_items WHERE active IS TRUE) THEN
        RAISE EXCEPTION 'Thiếu catalog amenities/furnishing_items. Hãy khởi động listing service để seed catalog trước.';
    END IF;
END $$;

